// The health of a shard, an index, or the cluster. An index reports the worst status of its shards, and the cluster reports the worst status of its indexes. Values are not case-sensitive.
type HealthStatus = string

const (
	// HealthStatusGreen. All shards are assigned.
	HealthStatusGreen HealthStatus = "green"

	// HealthStatusYellow. All primary shards are assigned, but one or more
	// replica shards are unassigned. If a node in the cluster fails, some data
	// could be unavailable until that node is repaired.
	HealthStatusYellow HealthStatus = "yellow"

	// HealthStatusRed. One or more primary shards are unassigned, so some data
	// is unavailable. This can occur briefly during cluster startup as primary
	// shards are assigned.
	HealthStatusRed HealthStatus = "red"
)

// Controls the amount of detail included in the cluster health response. Defaults to `cluster`, which reports only the cluster-wide health. `indices` adds the health of each index, and `shards` also adds the health of each shard within each index.
//
// `awareness_attributes` reports health for each value of an awareness attribute. It is required when `awareness_attribute` is set, and cannot be combined with an index target. An unrecognized value is treated as `cluster`.
type ClusterHealthLevel = string

const (
	// ClusterHealthLevelAwarenessAttributes. Reports health broken down by
	// each value of the cluster's awareness attributes, without per-index
	// detail. Must be used when `awareness_attribute` is set and cannot target
	// specific indexes.
	ClusterHealthLevelAwarenessAttributes ClusterHealthLevel = "awareness_attributes"

	// ClusterHealthLevelCluster. Reports only the cluster-wide health and
	// shard counts, the smallest response.
	ClusterHealthLevelCluster ClusterHealthLevel = "cluster"

	// ClusterHealthLevelIndices. Adds an `indices` object with the health and
	// shard counts of each index.
	ClusterHealthLevelIndices ClusterHealthLevel = "indices"

	// ClusterHealthLevelShards. Adds per-index health plus the health of each
	// shard within each index, the largest response.
	ClusterHealthLevelShards ClusterHealthLevel = "shards"
)

// Waits until all currently queued events with the given priority are processed.
